static void Check(bool v,const std::string& text){if(!v)throw std::runtime_error(text);++checks;}
static void Near(float a,float b,const std::string& text){Check(std::abs(a-b)<.002f,text);}
static void Same(const TransformComponent& a,const TransformComponent& b){auto x=TransformMatrix(a),y=TransformMatrix(b);for(int i=0;i<16;++i)Near(float(x[i]),float(y[i]),"Transform matches");}
static void Select(Application& app,std::initializer_list<Entity> entities){bool first=true;for(auto e:entities){app.GetEditorLayer().SelectViewportEntity(app,e,!first,false);first=false;}}
static Json Read(const std::filesystem::path& path){std::ifstream f(path);Json j;f>>j;return j;}
static Entity Named(const World& w,Entity root,const std::string& name){for(auto e:w.Subtree(root))if(auto* t=w.GetComponent<TagComponent>(e);t&&t->name==name)return e;throw std::runtime_error("Missing "+name);}
